import{_ as r,a0 as u,w as i,s,ao as l,I as n,x as o,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 15.04 系統中安裝 Logwatch | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04 系統中安裝 Logwatch | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04 系統中安裝 Logwatch | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04 系統中安裝 Logwatch | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150813 How to Install Logwatch on Ubuntu 15.04","title":"如何在 Ubuntu 15.04 系統中安裝 Logwatch","tag":"201508","desc":""},"relativePath":"201508/20150813 How to Install Logwatch on Ubuntu 15.04.md","filePath":"[post].md"}'),g={name:"201508/20150813 How to Install Logwatch on Ubuntu 15.04.md"};function d(c,t,h,w,m,b){const a=u("Link");return i(),s("div",null,[t[16]||(t[16]=l(`<h1 id="如何在-ubuntu-15-04-系統中安裝-logwatch" tabindex="-1">如何在 Ubuntu 15.04 系統中安裝 Logwatch <a class="header-anchor" href="#如何在-ubuntu-15-04-系統中安裝-logwatch" aria-label="Permalink to “如何在 Ubuntu 15.04 系統中安裝 Logwatch”">​</a></h1><p>大家好，今天我們會講述在 Ubuntu 15.04 操作系統上如何安裝 Logwatch 軟件，它也可以在各種 Linux 系統和類 Unix 系統上安裝。Logwatch 是一款可定製的日誌分析和日誌監控報告生成系統，它可以根據一段時間的日誌文件生成您所希望關注的詳細報告。它具有易安裝、易配置、可審查等特性，同時對其提供的數據的安全性上也有一些保障措施。Logwatch 會掃描重要的操作系統組件像 SSH、網站服務等的日誌文件，然後生成用户所關心的有價值的條目彙總報告。</p><h3 id="預安裝設置" tabindex="-1">預安裝設置 <a class="header-anchor" href="#預安裝設置" aria-label="Permalink to “預安裝設置”">​</a></h3><p>我們會使用 Ubuntu 15.04 版本的操作系統來部署 Logwatch，所以安裝 Logwatch 之前，要確保系統上郵件服務設置是正常可用的。因為它會每天把生成的報告通過日報的形式發送郵件給管理員。您的系統的源庫也應該設置可用，以便可以從通用源庫來安裝 Logwatch。</p><p>然後打開您 ubuntu 系統的終端，用 root 賬號登陸，在進入 Logwatch 的安裝操作前，先更新您的系統軟件包。</p><pre><code>root@ubuntu-15:~# apt-get update
</code></pre><h3 id="安裝-logwatch" tabindex="-1">安裝 Logwatch <a class="header-anchor" href="#安裝-logwatch" aria-label="Permalink to “安裝 Logwatch”">​</a></h3><p>只要你的系統已經更新和已經滿足前面説的先決條件，那麼就可以在您的機器上輸入如下命令來安裝 Logwatch。</p><pre><code>root@ubuntu-15:~# apt-get install logwatch
</code></pre><p>在安裝過程中，一旦您按提示按下“Y”鍵同意對系統修改的話，Logwatch 將會開始安裝一些額外的必須軟件包。</p><p>在安裝過程中會根據您機器上的郵件服務器設置情況彈出提示對 Postfix 設置的配置界面。在這篇教程中我們使用最容易的 “僅本地（Local only）” 選項。根據您的基礎設施情況也可以選擇其它的可選項，然後點擊“確定”繼續。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/21.png" alt="Potfix Configurations"></p><p>隨後您得選擇郵件服務器名，這郵件服務器名也會被其它程序使用，所以它應該是一個完全合格域名/全稱域名（FQDN）。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/31.png" alt="Postfix Setup"></p><p>一旦按下在 postfix 配置提示底端的 “OK”，安裝進程就會用 Postfix 的默認配置來安裝，並且完成 Logwatch 的整個安裝。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/41.png" alt="Logwatch Completion"></p><p>您可以在終端下發出如下命令來檢查 Logwatch 狀態，正常情況下它應該是激活狀態。</p><pre><code>root@ubuntu-15:~# service postfix status
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/51.png" alt="Postfix Status"></p><p>要確認 Logwatch 在默認配置下的安裝信息，可以如下示簡單的發出“logwatch” 命令。</p><pre><code>root@ubuntu-15:~# logwatch
</code></pre><p>上面執行命令的輸出就是終端下編制出的報表展現格式。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/61.png" alt="Logwatch Report"></p><h3 id="配置-logwatch" tabindex="-1">配置 Logwatch <a class="header-anchor" href="#配置-logwatch" aria-label="Permalink to “配置 Logwatch”">​</a></h3><p>在成功安裝好 Logwatch 後，我們需要在它的配置文件中做一些修改，配置文件位於如下所示的路徑。那麼，就讓我們用文本編輯器打開它，然後按需要做些變動。</p><pre><code>root@ubuntu-15:~# vim /usr/share/logwatch/default.conf/logwatch.conf
</code></pre><p><strong>輸出/格式化選項</strong></p><p>默認情況下 Logwatch 會以無編碼的文本打印到標準輸出方式。要改為以郵件為默認方式，需設置“Output = mail”，要改為保存成文件方式，需設置“Output = file”。所以您可以根據您的要求設置其默認配置。</p><pre><code>Output = stdout
</code></pre><p>如果使用的是因特網電子郵件配置，要用 Html 格式為默認出格式，需要修改成如下行所示的樣子。</p><pre><code>Format = text
</code></pre><p>現在增加默認的郵件報告接收人地址，可以是本地賬號也可以是完整的郵件地址，需要的都可以在這行上寫上</p><pre><code>MailTo = root
#MailTo = user@test.com
</code></pre><p>默認的郵件發送人可以是本地賬號，也可以是您需要使用的其它名字。</p><pre><code># complete email address.
MailFrom = Logwatch
</code></pre><p>對這個配置文件保存修改，至於其它的參數就讓它保持默認，無需改動。</p><p><strong>調度任務配置</strong></p><p>現在編輯在 “daily crons” 目錄下的 “00logwatch” 文件來配置從 logwatch 生成的報告需要發送的郵件地址。</p><pre><code>root@ubuntu-15:~# vim /etc/cron.daily/00logwatch
</code></pre>`,39)),n("p",null,[t[1]||(t[1]=o("在這兒您需要作用“--mailto ",-1)),e(a,{href:"mailto:user@test.com"},{default:p(()=>[...t[0]||(t[0]=[o("user@test.com",-1)])]),_:1}),t[2]||(t[2]=o("”來替換掉“--output mail”,然後保存文件。",-1))]),t[17]||(t[17]=l(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/71.png" alt="Logwatch Cronjob"></p><h3 id="生成報告" tabindex="-1">生成報告 <a class="header-anchor" href="#生成報告" aria-label="Permalink to “生成報告”">​</a></h3><p>現在我們在終端中執行“logwatch”命令來生成測試報告，生成的結果在終端中會以文本格式顯示出來。</p><pre><code>root@ubuntu-15:~#logwatch
</code></pre><p>生成的報告開始部分顯示的是執行的時間和日期。它包含不同的部分，每個部分以開始標識開始而以結束標識結束，中間顯示的是該部分的完整信息。</p><p>這兒顯示的是開始的樣子，它以顯示系統上所有安裝的軟件包的部分開始，如下所示：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/81.png" alt="dpkg status"></p><p>接下來的部分顯示的日誌信息是關於當前系統登錄會話、rsyslogs 和當前及最近的 SSH 會話信息。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/9.png" alt="logwatch report"></p><p>Logwatch 報告最後顯示的是安全方面的 sudo 日誌及根目錄磁盤使用情況，如下示：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/10.png" alt="Logwatch end report"></p><p>您也可以打開如下的文件來查看生成的 logwatch 報告電子郵件。</p><pre><code>root@ubuntu-15:~# vim /var/mail/root
</code></pre><p>您會看到發送給你配置的用户的所有已生成的郵件及其郵件遞交狀態。</p><h3 id="更多詳情" tabindex="-1">更多詳情 <a class="header-anchor" href="#更多詳情" aria-label="Permalink to “更多詳情”">​</a></h3><p>Logwatch 是一款很不錯的工具，可以學習的很多很多，所以如果您對它的日誌監控功能很感興趣的話，也以通過如下所示的簡短命令來獲得更多幫助。</p><pre><code>root@ubuntu-15:~# man logwatch
</code></pre><p>上面的命令包含所有關於 logwatch 的用户手冊，所以仔細閲讀，要退出手冊的話可以簡單的輸入“q”。</p><p>關於 logwatch 命令的使用，您可以使用如下所示的幫助命令來獲得更多的詳細信息。</p><pre><code>root@ubuntu-15:~# logwatch --help
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>教程結束，您也學會了如何在 Ubuntu 15.04 上對 Logwatch 的安裝、配置等全部設置指導。現在您就可以自定義監控您的系統日誌，不管是監控所有服務的運行情況還是對特定的服務在指定的時間發送報告都可以。所以，開始使用這工具吧，無論何時有問題或想知道更多關於 logwatch 的使用的都可以給我們留言。</p><hr>`,23)),n("p",null,[t[4]||(t[4]=o("via: ",-1)),e(a,{href:"http://linoxide.com/ubuntu-how-to/install-use-logwatch-ubuntu-15-04/"},{default:p(()=>[...t[3]||(t[3]=[o("http://linoxide.com/ubuntu-how-to/install-use-logwatch-ubuntu-15-04/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=o("作者：",-1)),e(a,{href:"http://linoxide.com/author/kashifs/"},{default:p(()=>[...t[5]||(t[5]=[o("Kashif Siddique",-1)])]),_:1}),t[9]||(t[9]=o(" 譯者：",-1)),e(a,{href:"https://github.com/runningwater"},{default:p(()=>[...t[6]||(t[6]=[o("runningwater",-1)])]),_:1}),t[10]||(t[10]=o(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=o("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原創翻譯，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...t[12]||(t[12]=[o("Linux中國",-1)])]),_:1}),t[15]||(t[15]=o(" 榮譽推出",-1))])])}const T=r(g,[["render",d]]);export{x as __pageData,T as default};
